import React, { useEffect, useState, useRef } from 'react';
import { useColorMode } from 'theme-ui';
import Map, { Source, Layer, Marker, NavigationControl } from '@vis.gl/react-maplibre';
import maplibregl from 'maplibre-gl';
import * as toGeoJSON from '@mapbox/togeojson';
import html2canvas from 'html2canvas';
import 'maplibre-gl/dist/maplibre-gl.css';

const STYLES = {
  light: 'https://tiles.openfreemap.org/styles/liberty',
  dark: 'https://tiles.openfreemap.org/styles/fiord',
};

// Collect every coordinate from all features into a [[west, south], [east, north]] bounds
const getBounds = (geoJson) => {
  let minLng = Infinity, minLat = Infinity, maxLng = -Infinity, maxLat = -Infinity;
  for (const feature of geoJson.features) {
    const g = feature.geometry;
    if (!g) continue;
    const paths = g.type === 'LineString' ? [g.coordinates]
      : g.type === 'MultiLineString' ? g.coordinates
      : g.type === 'Point' ? [[g.coordinates]]
      : [];
    for (const path of paths) {
      for (const c of path) {
        if (c[0] < minLng) minLng = c[0];
        if (c[0] > maxLng) maxLng = c[0];
        if (c[1] < minLat) minLat = c[1];
        if (c[1] > maxLat) maxLat = c[1];
      }
    }
  }
  if (minLng === Infinity) return null;
  return [[minLng, minLat], [maxLng, maxLat]];
};

const GpxMap = ({ src }) => {
  const [colorMode] = useColorMode();
  const mapStyle = STYLES[colorMode] || STYLES.light;
  const [geoData, setGeoData] = useState(null);
  const [trackBounds, setTrackBounds] = useState(null);
  const [mapReady, setMapReady] = useState(false);
  const [endpoints, setEndpoints] = useState({ start: null, end: null });
  const [rawStats, setRawStats] = useState({ distanceMeters: 0, elevationMeters: 0 });
  const [isMetric, setIsMetric] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);

  // 1. Ref specifically for the Map container (to exclude stats)
  const mapContainerRef = useRef(null);

  useEffect(() => {
    if (!src) return;
    fetch(src)
      .then(r => r.text())
      .then(str => {
        const gpx = new DOMParser().parseFromString(str, "text/xml");
        const converted = toGeoJSON.gpx(gpx);
        setGeoData(converted);
        setTrackBounds(getBounds(converted));
        const track = converted.features.find(f => f.geometry.type === 'LineString');
        if (track) {
          const coords = track.geometry.coordinates;
          let dist = 0;
          let ele = 0;
          for (let i = 0; i < coords.length - 1; i++) {
            const p1 = coords[i];
            const p2 = coords[i + 1];
            dist += maplibregl.LngLat.convert([p1[0], p1[1]]).distanceTo(
              maplibregl.LngLat.convert([p2[0], p2[1]])
            );
            if (p2[2] && p1[2]) {
              const diff = p2[2] - p1[2];
              if (diff > 0) ele += diff;
            }
          }
          setEndpoints({
            start: [coords[0][0], coords[0][1]],
            end: [coords[coords.length - 1][0], coords[coords.length - 1][1]]
          });
          setRawStats({ distanceMeters: dist, elevationMeters: ele });
        }
      })
      .catch(err => console.error("Failed to load GPX:", err))
      .finally(() => setMapReady(true));
  }, [src]);

  const displayDist = isMetric
    ? (rawStats.distanceMeters / 1000).toFixed(2) + " km"
    : (rawStats.distanceMeters * 0.000621371).toFixed(2) + " mi";

  const displayEle = isMetric
    ? Math.round(rawStats.elevationMeters) + " m"
    : Math.round(rawStats.elevationMeters * 3.28084) + " ft";

  if (typeof window === 'undefined') return <div style={{ height: '400px', background: '#eee' }} />;

  const handleDownloadImage = async () => {
    if (mapContainerRef.current) {
      setIsDownloading(true);
      try {
        const canvas = await html2canvas(mapContainerRef.current, {
          useCORS: true,
          allowTaint: true,
          scale: 2,
          // The "onclone" hook allows us to modify the temporary DOM used for the screenshot
          onclone: (clonedDoc) => {
            // 1. Hide the zoom controls (+/- buttons) for a cleaner image
            const controls = clonedDoc.querySelectorAll('.maplibregl-ctrl-group');
            controls.forEach(c => { c.style.display = 'none'; });
          }
        });

        const link = document.createElement('a');
        link.download = `route-map-square.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
      } catch (err) {
        console.error("Screenshot failed:", err);
      }
      setIsDownloading(false);
    }
  };

  return (
    <div style={{ width: '100%', borderRadius: '12px', overflow: 'hidden', border: '1px solid #eee', background: 'white' }}>

      {/* 2. Map Container: Added Ref here + aspectRatio */}
      <div
        ref={mapContainerRef}
        style={{
          width: '100%',
          aspectRatio: '4 / 5',
          position: 'relative',
          // Clip the WebGL canvas to the card's rounded top corners.
          // overflow/border-radius alone can fail to clip GPU-composited canvases;
          // clip-path is applied at composite time and always works.
          borderRadius: '12px 12px 0 0',
          overflow: 'hidden',
          clipPath: 'inset(0 round 12px 12px 0 0)',
        }}
      >
        {mapReady && (
          <Map
            mapLib={maplibregl}
            mapStyle={mapStyle}
            initialViewState={
              trackBounds
                ? { bounds: trackBounds, fitBoundsOptions: { padding: 60 } }
                : { longitude: 0, latitude: 0, zoom: 2 }
            }
            renderWorldCopies={false}
            preserveDrawingBuffer
            style={{ height: '100%', width: '100%' }}
          >
            {geoData && (
              <Source id="gpx-track" type="geojson" data={geoData}>
                <Layer
                  id="gpx-track-line"
                  type="line"
                  layout={{ 'line-join': 'round', 'line-cap': 'round' }}
                  paint={{ 'line-color': '#3498db', 'line-width': 5 }}
                />
              </Source>
            )}
            {endpoints.start && (
              <Marker longitude={endpoints.start[0]} latitude={endpoints.start[1]} color="#2ecc71" />
            )}
            {endpoints.end && (
              <Marker longitude={endpoints.end[0]} latitude={endpoints.end[1]} color="#e74c3c" />
            )}
            <NavigationControl position="bottom-left" showCompass={false} />
          </Map>
        )}
      </div>

      {/* Stats Bar (Outside the ref, so it won't be in the screenshot) */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: '1fr 1fr auto',
        alignItems: 'center',
        padding: '12px 15px',
        background: '#fff',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        borderTop: '1px solid #eee'
      }}>
        <div style={{ textAlign: 'center', borderRight: '1px solid #eee' }}>
          <small style={{ display: 'block', color: '#888', textTransform: 'uppercase', fontSize: '10px', fontWeight: '600', marginBottom: '2px' }}>
            Distance
          </small>
          <div style={{ fontWeight: '700', fontSize: '16px', color: '#222', fontVariantNumeric: 'tabular-nums' }}>
            {displayDist}
          </div>
        </div>

        <div style={{ textAlign: 'center' }}>
          <small style={{ display: 'block', color: '#888', textTransform: 'uppercase', fontSize: '10px', fontWeight: '600', marginBottom: '2px' }}>
            Elevation Gain
          </small>
          <div style={{ fontWeight: '700', fontSize: '16px', color: '#222', fontVariantNumeric: 'tabular-nums' }}>
            {displayEle}
          </div>
        </div>

        <div style={{ paddingLeft: '15px', display: 'flex', flexDirection: 'column', gap: '5px' }}>
          <button
            onClick={() => setIsMetric(!isMetric)}
            style={{
              background: '#f8f9fa',
              border: '1px solid #dcdcdc',
              borderRadius: '6px',
              width: '100px',
              padding: '6px 0',
              fontSize: '10px',
              cursor: 'pointer',
              fontWeight: '700',
              color: '#666',
              textTransform: 'uppercase'
            }}
          >
            {isMetric ? 'Metric' : 'Imperial'}
          </button>

          <button
            onClick={handleDownloadImage}
            disabled={isDownloading}
            style={{
              background: '#3498db',
              border: 'none',
              borderRadius: '6px',
              width: '100px',
              padding: '6px 0',
              fontSize: '10px',
              cursor: 'pointer',
              fontWeight: '700',
              color: '#fff',
              textTransform: 'uppercase',
              opacity: isDownloading ? 0.7 : 1
            }}
          >
            {isDownloading ? 'Saving...' : '📸 Save Map'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default GpxMap;
